import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import SearchForm from '../components/SearchForm';
import RouteList from '../components/RouteList';
import { useNavigate } from 'react-router-dom';
import '../styles/home.css';

const Home = () => {
  const [routes, setRoutes] = useState([]);
  const [filteredRoutes, setFilteredRoutes] = useState([]);
  const [searchPerformed, setSearchPerformed] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const checkEmailConfirmation = () => {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('emailConfirmed')) {
        navigate('/', { replace: true });
        setTimeout(() => alert('✅ Ваш email успешно подтвержден!'), 300);
      }
    };

    const fetchRoutes = async () => {
      try {
        const { data } = await axios.get('/api/routes');
        setRoutes(data);
        setFilteredRoutes(data);
        setIsLoading(false);
      } catch (err) {
        console.error('Ошибка загрузки маршрутов:', err);
        setIsLoading(false);
      }
    };

    checkEmailConfirmation();
    fetchRoutes();
  }, [navigate]);

  const handleSearch = useCallback(({ from, to, date }) => {
    const filtered = routes.filter(route => {
      const matchFrom = from ? route.from?.toLowerCase().includes(from.toLowerCase()) : true;
      const matchTo = to ? route.to?.toLowerCase().includes(to.toLowerCase()) : true;
      const routeDate = new Date(route.date);
      const searchDate = new Date(date);
      return matchFrom && matchTo && (!date || 
        routeDate.getFullYear() === searchDate.getFullYear() &&
        routeDate.getMonth() === searchDate.getMonth() &&
        routeDate.getDate() === searchDate.getDate());
    });
    
    setFilteredRoutes(filtered);
    setSearchPerformed(true);
    window.scrollTo({ top: 500, behavior: 'smooth' });
  }, [routes]);

  const handleSearchReset = useCallback(() => {
    if (searchPerformed) {
      setSearchPerformed(false);
      setFilteredRoutes(routes);
    }
  }, [searchPerformed, routes]);

  return (
    <div className="home-page">
      <section className="hero-section">
        <div className="hero-content">
          <h1 className="hero-title">Найдите идеальное путешествие</h1>
          <p className="hero-subtitle">Откройте для себя лучшие направления по выгодным ценам</p>
        </div>
      </section>

      <section className="main-layout">
        <div className={`content-wrapper ${searchPerformed ? 'search-done' : 'search-pending'}`}>
          <main className="main-content">
            <SearchForm 
              onSearch={handleSearch}
              onFocus={handleSearchReset}
              wide={!searchPerformed}
              isLoading={isLoading}
            />
          </main>

          <aside className={`sidebar ${searchPerformed ? 'visible' : ''}`}>
            <div className="sidebar-card help-card">
              <h4>🚀 Помощь в поездке</h4>
              <ul className="help-list">
                <li className="help-item">📞 Горячая линия</li>
                <li className="help-item">📄 Условия возврата</li>
                <li className="help-item">📍 Пункты отправления</li>
                <li className="help-item">💳 Оплата онлайн</li>
              </ul>
            </div>
            <div className="sidebar-card tip-card">
              <h4>💡 Советы</h4>
              <p className="tip-text">Выбирайте рейсы вне часа пик — дешевле и свободнее.</p>
            </div>
          </aside>
        </div>

        {searchPerformed && (
          <div className="routes-wrapper">
            {filteredRoutes.length > 0 ? (
              <RouteList routes={filteredRoutes} />
            ) : (
              <div className="no-routes">
                🗺️ Маршруты не найдены. Попробуйте изменить параметры поиска
              </div>
            )}
          </div>
        )}
      </section>

       <section className="features-wrapper">
        <h2 className="features-title">Почему выбирают нас</h2>
        <div className="features-grid three-columns">
          <div className="feature-item large">
            <div className="feature-icon">⚡</div>
            <div>
              <h3>Быстро и удобно</h3>
              <p>Ищите и бронируйте билеты за пару кликов. Наш сервис работает мгновенно.</p>
            </div>
          </div>

          <div className="feature-item large">
            <div className="feature-icon">🛡️</div>
            <div>
              <h3>Надёжность гарантирована</h3>
              <p>Работаем только с проверенными перевозчиками. Поддержка 24/7.</p>
            </div>
          </div>

          <div className="feature-item large">
            <div className="feature-icon">💰</div>
            <div>
              <h3>Экономьте с нами</h3>
              <p>Лучшие цены без скрытых платежей. Прозрачные условия бронирования.</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
